+fn pattern(width: u32, height: u32, frame: usize) -> DynamicImage {
+    let data = (0..width as usize * height as usize * 3)
+        .map(|i| ((i * 37 + i / 13 + frame * 41) % 256) as u8)
+        .collect();
+    DynamicImage::ImageRgb8(RgbImage::from_raw(width, height, data).unwrap())
